  auto *inst = &inst_;
  (void)inst;
  int flat_offset = (inst->seg != 0) ? (inst->offset | (inst->pad_12 << 12)) : inst->offset;
  if (flat_offset)
    out += " offset:" + std::to_string(flat_offset);
  if (inst->glc)
    out += " glc";
  if (inst->slc)
    out += " slc";
